class SuperVTable {
    public void methodA() { System.out.println("Super: methodA()"); }
    public void methodB() { System.out.println("Super: methodB()"); }
}

class SubVTable extends SuperVTable {
    // Overrides methodB only
    @Override
    public void methodB() {
        System.out.println("Sub: methodB() [Overridden v-table pointer]");
    }

    // Subclass addition
    public void methodC() {
        System.out.println("Sub: methodC()");
    }
}

public class VTableSimulationDemo {
    public static void main(String[] args) {
        SuperVTable ref = new SubVTable();

        // 1. methodA: Un-overridden -> v-table points to SuperVTable.methodA
        ref.methodA();

        // 2. methodB: Overridden -> v-table points to SubVTable.methodB
        ref.methodB();
    }
}

