class Worker {
    public void clockIn() { System.out.println("Worker clocked in"); }
}
class Surgeon extends Worker {
    @Override public void clockIn() { System.out.println("Surgeon sanitizing for OR at 06:00"); }
}
class Pilot extends Worker {
    @Override public void clockIn() { System.out.println("Pilot completing pre-flight checklist"); }
}
class Chef extends Worker {
    @Override public void clockIn() { System.out.println("Chef prepping kitchen mise en place"); }
}

public class LateBindingArrayDemo {
    public static void main(String[] args) {
        Worker[] shift = new Worker[] { new Surgeon(), new Pilot(), new Chef() };

        // At each iteration, invokevirtual inspects the heap object and dispatches
        for (Worker w : shift) {
            w.clockIn();
        }
    }
}

