class BaseService {
    public void start() {
        System.out.println("Base service started");
    }
    public void healthCheck() {
        System.out.println("Base service health check OK");
    }
    public void stop() {
        System.out.println("Base service stopped");
    }
}

class MicroService extends BaseService {
    @Override
    public void healthCheck() {
        System.out.println("Microservice health: 100% OK (Latency: 2ms)");
    }
}

public class Main {
    public static void main(String[] args) {
        BaseService svc = new MicroService();
        svc.start();
        svc.healthCheck();
        svc.stop();
    }
}

class Asset {
